const payload = $input.first().json;
const data = payload.data || payload;
const currentSpent = parseFloat(data.currentSpent || 0);
const limit = parseFloat(data.limit || 1);
const category = data.category || 'General';
const month = data.month || new Date().toISOString().slice(0, 7);
const userId = payload.userId || data.userId;
const pct = Math.round((currentSpent / limit) * 100);

const isOverLimit = pct >= 100;
const isWarning = pct >= 80;
const severity = isOverLimit ? 'critical' : 'warning';

const message = isOverLimit
  ? `🚨 Budget Exceeded: You have spent ₹${currentSpent.toLocaleString()} (${pct}%) against your ₹${limit.toLocaleString()} limit for ${category}.`
  : `⚠️ Budget Warning: ${category} spending has reached ${pct}% (₹${currentSpent.toLocaleString()} / ₹${limit.toLocaleString()}).`;

return [{
  json: {
    userId,
    category,
    currentSpent,
    limit,
    pct,
    month,
    severity,
    message,
    logId: payload.logId,
    timestamp: new Date().toISOString()
  }
}];
